cd /home/user/rork-app && echo "=== Get raw login response to find JWT field ===" && \
LOGIN=$(timeout 30 curl -s -X POST "https://api.ivxholding.com/api/members/login" \
  -H "Content-Type: application/json" \
  -d '{"email":"iperez4242@gmail.com","password":"X146corp@1x146corp$$1"}' 2>&1) && \
echo "$LOGIN" | python3 -c "
import sys, json
d = json.load(sys.stdin)
print('Top-level keys:', list(d.keys()))
# Find the JWT
for k in ['token','accessToken','access_token','jwt','sessionToken']:
    v = d.get(k)
    if v and isinstance(v, str) and len(v) > 50:
        print(f'JWT found in field: {k} (len={len(v)})')
        print(v[:50] + '...')
if 'session' in d:
    s = d['session']
    if isinstance(s, dict):
        print('session keys:', list(s.keys()))
        for k in ['access_token','accessToken','token']:
            v = s.get(k)
            if v and isinstance(v, str) and len(v) > 50:
                print(f'JWT found in session.{k} (len={len(v)})')
                print(v[:50] + '...')
# Check data nested
if 'data' in d:
    dd = d['data']
    if isinstance(dd, dict):
        print('data keys:', list(dd.keys()))
        for k in ['token','accessToken','access_token','jwt']:
            v = dd.get(k)
            if v and isinstance(v, str) and len(v) > 50:
                print(f'JWT found in data.{k} (len={len(v)})')
" 2>/dev/null

